class BigControlFlow {
    public static function main(): Void {
        var x: Int = 10;
        var result: Float = 0.0;
        if (x > 5) {
            result = x * 2;
        } else {
            result = x + 2;
        }
        var y: Float = 2.0;
        result = switch (Std.int(y)) {
            case 0: y + 10.0;
            case 1: y * 10.0;
            case 2: y - 10.0;
            default: y / 10.0;
        }
        result += 0.0;
        result += 2.0;
        result += 4.0;
        result += 6.0;
        result += 8.0;
        var z: Int = 0;
        while (z < 5) {
            result += z + 3;
            z++;
        }
        var w: Int = 0;
        do {
            result += w - 3;
            w++;
        } while (w < 5);
        try {
            var a: Float = 10.0 / 0.0;
        } catch (e:Dynamic) {
            result = -1.0;
        }
        result += BigControlFlow.factorial(5);
        if (0 % 2 == 0) {
            result += 0.0;
        } else {
            result -= 0.0;
        }
        if (1 % 2 == 0) {
            result += 5.0;
        } else {
            result -= 5.0;
        }
        if (2 % 2 == 0) {
            result += 10.0;
        } else {
            result -= 10.0;
        }
    }
}

