$LoopNested.main.pseudo:
class LoopNested {
    public static function main(): Void {
        var b: Int = 69;
        while (true) {
            b *= 2;
            if (b > 1000) {
                break;
            }
            var a: Int = 0;
            if (a > 1) {
                a = 1;
            } else {
                a = 2;
                return;
            }
            do {
                b *= 2;
            } while (b <= 1000);
        }
    }
}

