original.content:
class Nested {
    static function main() {
        var b = 512.0;
        while (b &gt; 5) {
            b /= 2;
            if (b &lt; 10) {
                while (b &lt; 100) {
                    b *= 2;
                    if (b &gt; 50) {
                        break;
                    }
                }
            }
        }
    }
}

