$LoopControlCase.findLastPositive.pseudo:
class LoopControlCase {
    public static function findLastPositive(arr: Array<Int>): Int {
        var i: Int = arr.length - 1;
        while (i >= 0) {
            if (arr[i] > 0) {
                return arr[i];
            }
            i--;
        }
        return -1;
    }
}

