$LoopControlCase.sumUntilNegative.pseudo:
class LoopControlCase {
    public static function sumUntilNegative(arr: Array<Int>): Int {
        var total: Int = 0;
        var i: Int = 0;
        while (i < arr.length) {
            if (arr[i] < 0) {
                return total;
            }
            total += arr[i];
            i++;
        }
        return total;
    }
}

