class HeapsSkinSplit {
    public function isSub(a: Array<Joint>, b: Array<Joint>): Bool {
        var var6: Int = 0;
        var j: Int = 0;
        var max: Int = b.length;
        for (e in a) {
            while (true) {
                var6 = j;
                j++;
                if (e != b[var6]) {
                    if (j >= max) {
                        return false;
                    }
                } else {
                    break;
                }
            }
        }
        return true;
    }
}

