HeapsSkinSplit.merge.pseudo:
class HeapsSkinSplit {
    public function merge(permuts: Array<Permut>): Bool {
        var var11: Bool = false;
        var var2: Int = 0;
        while (var2 < permuts.length) {
            var p1: Permut = permuts[var2];
            var2++;
            for (p2 in permuts) {
                if (p1 != p2) {
                    if (p1.material == p2.material) {
                        var11 = this.isSub(p1.joints, p2.joints);
                        if (var11) {
                            for (t in p1.triangles) {
                                p2.triangles.push(t);
                            }
                            permuts.remove(p1);
                            return true;
                        }
                    }
                }
            }
        }
        return false;
    }
}

