HeapsSkinSplit.jointsDiff.pseudo:
class HeapsSkinSplit {
    public function jointsDiff(p1: Permut, p2: Permut): Int {
        var diff: Int = 0;
        var i: Int = 0;
        var j: Int = 0;
        var imax: Int = p1.joints.length;
        var jmax: Int = p2.joints.length;
        while (i < imax) {
            if (j < jmax) {
                var j1: Joint = p1.joints[i];
                var j2: Joint = p2.joints[j];
                if (j1 == j2) {
                    i++;
                    j++;
                } else {
                    diff++;
                    if (j1.bindIndex < j2.bindIndex) {
                        i++;
                    } else {
                        j++;
                    }
                }
            } else {
                break;
            }
        }
        return diff + imax - i + jmax - j;
    }
}

