class PreIncCond {
    public static function main(): Void {
        var i: Int = 0;
        while (true) {
            i++;
            if (i >= 4) {
                break;
            }
            Sys.println(i);
        }
        var j: Int = 0;
        do {
            j--;
            Sys.println(j);
        } while (j > -3);
    }
}

