class UnrolledLoopCatch {
    public static function main(): Void {
        var var6: String = "";
        try {
            Sys.println(0);
        } catch (e:String) {
            var6 = e + 0;
            Sys.println(var6);
        }
        Sys.println("tail " + 0);
        try {
            throw "skip";
        } catch (e:String) {
            var6 = e + 1;
            Sys.println(var6);
        }
        Sys.println("tail " + 1);
        try {
            Sys.println(2);
        } catch (e:String) {
            var6 = e + 2;
            Sys.println(var6);
        }
        Sys.println("tail " + 2);
    }
}

